(()=>{'use strict';
const embedded=!!document.getElementById('production-detail');
const D=window.ProductionData,$=id=>document.getElementById(id),params=new URLSearchParams(location.search),E=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let lang=params.get('lang')==='km'?'km':'en',from=params.get('from')||'2026-09-22',to=params.get('to')||'2026-09-28',product=params.get('product')||'all',scenario=params.get('scenario')||'',loading=true,failed=scenario==='error',error='',detail=null,history=[],opener=null;
const valid=d=>/^\d{4}-\d{2}-\d{2}$/.test(d)&&Number.isFinite(Date.parse(d))&&new Date(d+'T12:00:00Z').toISOString().slice(0,10)===d;
if(!valid(from)||!valid(to)||from>to){from='2026-09-22';to='2026-09-28';}if(!D.products.some(p=>p.id===product))product='all';
if(scenario==='production-only')from=to='2026-09-20';if(scenario==='sales-only')from=to='2026-09-21';if(scenario==='empty')from=to='2026-09-30';if(scenario==='units')from=to='2026-09-29';
const L=(a,b)=>lang==='km'?b:a,N=a=>L(...a),num=n=>new Intl.NumberFormat(lang==='km'?'km-KH':'en-US').format(n),date=d=>new Intl.DateTimeFormat(lang==='km'?'km-KH':'en-GB',{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'}).format(new Date(d+'T12:00:00Z'));
const b=(act,text,extra='')=>`<button type="button" data-act="${act}" ${extra}>${text}</button>`,field=(a,v)=>`<div><dt>${a}</dt><dd>${v}</dd></div>`,channel=k=>({production:L('Production','ផលិតកម្ម'),walkin:L('Walk-in sales','ការលក់ផ្ទាល់'),driver:L('Driver sales','ការលក់តាមអ្នកបើកបរ'),sales:L('All sales','ការលក់ទាំងអស់'),all:L('All sources','ប្រភពទាំងអស់')})[k];
const query=()=>`lang=${lang}&from=${from}&to=${to}`,available=()=>from>='2026-09-20'&&to<='2026-09-30';
function nav(){return `<nav aria-label="${L('Home','ទំព័រដើម')}"><p class="nav-caption">${L('HOME','ទំព័រដើម')}</p><a href="home.html?lang=${lang}">${L('Home','ទំព័រដើម')}</a></nav><nav aria-label="${L('Navigation','ម៉ឺនុយ')}"><p class="nav-caption">${L('SALES','ការលក់')}</p><a href="index.html?lang=${lang}">${L('Walk-in sales','ការលក់ផ្ទាល់')}</a><a href="driver-sales.html?lang=${lang}">${L('Driver sales','ការលក់តាមអ្នកបើកបរ')}</a><a href="debt-collection.html?lang=${lang}">${L('Debt collection','ការប្រមូលបំណុល')}</a><p class="nav-caption">${L('OPERATIONS','ប្រតិបត្តិការ')}</p><a href="dispatch-planning.html?lang=${lang}">${L('Dispatch Planning','រៀបចំដំណើរ')}</a><p class="nav-caption">${L('FINANCE','ហិរញ្ញវត្ថុ')}</p><a href="daily-finance.html?lang=${lang}">${L('Daily Finance','ហិរញ្ញវត្ថុប្រចាំថ្ងៃ')}</a><p class="nav-caption">${L('REPORTING','របាយការណ៍')}</p><a href="executive-overview.html?${query()}">${L('Executive overview','ទិដ្ឋភាពទូទៅសម្រាប់ថ្នាក់ដឹកនាំ')}</a><a aria-current="page" href="production-sales.html?${query()}">${L('Production vs sales','ផលិតកម្មធៀបនឹងការលក់')}</a></nav>`;}
function qty(r,key,k){const incomplete=!available()||(scenario==='pending'&&k!=='production')||r.invalid.some(x=>k==='all'||(k==='sales'&&x.kind!=='production')||x.kind===k);return b('sources',`<span>${num(r[key])}${incomplete?`<span class="ps-subtotal">${L('Comparable subtotal','សរុបរងដែលអាចប្រៀបធៀប')}</span>`:''}</span>`,`class="table-link qty" data-product="${r.id}" data-kind="${k}" aria-label="${E(N(r.name)+' · '+channel(k)+': '+num(r[key]))}"`);}
function diff(r){if(scenario==='pending'||!available())return L('Incomplete','មិនពេញលេញ');return r.difference==null?L('Not yet comparable','មិនទាន់អាចប្រៀបធៀប'):`${r.difference>0?'+':r.difference<0?'−':''}${num(Math.abs(r.difference))}`;}
function state(title,text,action=''){return `<div class="state-box"><h2>${title}</h2><p>${text}</p>${action}</div>`;}
function body(){if(loading)return `<div role="status" aria-live="polite"><p>${L('Loading recorded quantities…','កំពុងផ្ទុកបរិមាណបានកត់ត្រា…')}</p><div class="loading-grid">${'<div class="skeleton" aria-hidden="true"></div>'.repeat(3)}</div></div>`;if(failed)return state(L('Could not load the report','មិនអាចផ្ទុករបាយការណ៍'),L('Your filters are preserved. Try loading again.','តម្រងរបស់អ្នកត្រូវបានរក្សាទុក។ សូមសាកល្បងម្តងទៀត។'),b('retry',L('Retry','សាកល្បងម្តងទៀត')));if(to<'2026-09-20'||from>'2026-09-30')return state(L('History unavailable','មិនមានប្រវត្តិ'),L('This sample covers 20–30 September 2026. Dates outside that range are unavailable, not zero activity.','គំរូនេះគ្របដណ្តប់ថ្ងៃទី ២០–៣០ កញ្ញា ២០២៦។ កាលបរិច្ឆេទក្រៅនេះមិនមានទិន្នន័យ មិនមែនសកម្មភាពសូន្យទេ។'));
const rs=D.summary(from,to,product),records=D.records(from,to,product),bad=rs.reduce((s,r)=>s+r.invalid.length,0);if(!records.length)return state(L('No records in this period','គ្មានកំណត់ត្រាក្នុងរយៈពេលនេះ'),L('No production batches or actual sales match these filters. Try another period or product.','គ្មានកំណត់ត្រាផលិតកម្ម ឬការលក់ជាក់ស្តែងត្រូវនឹងតម្រងនេះទេ។ សូមជ្រើសរយៈពេល ឬផលិតផលផ្សេង។'));
return `${!available()?`<div class="ps-warning">${L('Incomplete coverage: sample records are available only for 20–30 September 2026. Figures are known subtotals, not full-period totals.','ទិន្នន័យមិនពេញលេញ៖ មានកំណត់ត្រាគំរូតែថ្ងៃទី ២០–៣០ កញ្ញា ២០២៦។ តួលេខជាសរុបរងដែលដឹង មិនមែនសរុបរយៈពេលពេញទេ។')}</div>`:''}${scenario==='pending'?`<div class="ps-warning"><strong>${L('Return records pending · DSP-0928-02','រង់ចាំកំណត់ត្រាត្រឡប់ · DSP-0928-02')}</strong><p>${L('Driver receipts have not all been entered. Sales below are recorded quantities only; the remaining quantity is unknown.','បង្កាន់ដៃអ្នកបើកបរមិនទាន់បានបញ្ចូលទាំងអស់។ បរិមាណលក់ខាងក្រោមជាចំនួនបានកត់ត្រាប៉ុណ្ណោះ។ បរិមាណនៅសល់មិនទាន់ដឹង។')}</p>${b('pending',L('View dispatch context','មើលព័ត៌មានដំណើរ'))}</div>`:''}${bad?`<div class="ps-warning" role="status"><strong>${L('Incomplete comparison','ការប្រៀបធៀបមិនពេញលេញ')}</strong><p>${num(bad)} ${L('source lines have missing or incompatible units. Known quantities are shown; affected differences are unavailable.','បន្ទាត់ប្រភពមានឯកតាខ្វះ ឬមិនត្រូវគ្នា។ បង្ហាញតែបរិមាណដែលដឹង ហើយមិនអាចគណនាភាពខុសគ្នាដែលរងផលប៉ះពាល់។')}</p></div>`:''}<section class="report-section"><div class="table-wrap ps-table-wrap"><table class="ps-table"><caption>${L('Recorded quantities by product','បរិមាណបានកត់ត្រាតាមផលិតផល')}</caption><thead><tr>${[L('Product','ផលិតផល'),L('Unit','ឯកតា'),L('Produced','បានផលិត'),L('Walk-in sales','លក់ផ្ទាល់'),L('Driver sales','លក់តាមអ្នកបើកបរ'),L('Total sold','លក់សរុប'),L('Production − sales','ផលិតកម្ម − ការលក់')].map((x,i)=>`<th scope="col" class="${i>1?'num':''}">${x}</th>`).join('')}</tr></thead><tbody>${rs.map(r=>`<tr><td>${b('sources',N(r.name),`class="table-link" data-product="${r.id}" data-kind="all"`)}</td><td>${N(r.unit)}</td><td class="num">${qty(r,'production','production')}</td><td class="num">${qty(r,'walkin','walkin')}</td><td class="num">${qty(r,'driver','driver')}</td><td class="num">${qty(r,'sold','sales')}</td><td class="num">${diff(r)}</td></tr>`).join('')}</tbody></table></div><div class="ps-mobile">${rs.map(r=>`<article class="ps-product"><header><h2>${N(r.name)}</h2><span class="pill">${N(r.unit)}</span></header><div class="ps-values">${[['production','production',L('Produced','បានផលិត')],['sold','sales',L('Total sold','លក់សរុប')],['walkin','walkin',L('Walk-in','លក់ផ្ទាល់')],['driver','driver',L('Driver','អ្នកបើកបរ')]].map(([key,k,label])=>b('sources',`<span>${label}</span><strong>${num(r[key])}${!available()||r.invalid.length||scenario==='pending'?`<small class="ps-subtotal">${L('Known subtotal','សរុបរងដែលដឹង')}</small>`:''}</strong>`,`data-product="${r.id}" data-kind="${k}"`)).join('')}</div>${r.invalid.length?`<p class="subtle">${L('Known comparable subtotals only','តែសរុបរងដែលអាចប្រៀបធៀប')}</p>`:''}<div class="ps-result"><span>${L('Production − sales','ផលិតកម្ម − ការលក់')}</span><strong>${diff(r)}</strong></div></article>`).join('')}</div><p class="ps-note">${L('Difference is recorded production minus recorded sales—not verified stock, waste, theft or profit. Sales can include ice produced before this period.','ភាពខុសគ្នាគឺផលិតកម្មបានកត់ត្រា ដកការលក់បានកត់ត្រា មិនមែនស្តុកដែលបានផ្ទៀងផ្ទាត់ កាកសំណល់ ចោរកម្ម ឬប្រាក់ចំណេញទេ។ ការលក់អាចរួមមានទឹកកកផលិតមុនរយៈពេលនេះ។')}</p></section><div class="ps-context"><div class="od-field"><strong>${L('Actual sales, regardless of payment','ការលក់ជាក់ស្តែង មិនអាស្រ័យលើការទូទាត់')}</strong><span class="subtle">${L('Paid, partially paid and unpaid sales all contribute quantities.','ការលក់បានទូទាត់ បង់មួយផ្នែក និងជំពាក់ សុទ្ធតែរួមក្នុងបរិមាណ។')}</span></div><div class="od-field"><strong>${L('Every product stands alone','ផលិតផលនីមួយៗដាច់ដោយឡែក')}</strong><span class="subtle">${L('No combined total across products, blocks or bags.','មិនមានសរុបរួមរវាងផលិតផល ដុំ ឬបាវ។')}</span></div></div>`;}
function render(){if(embedded){const host=$('production-report-content');if(host)host.innerHTML=fragment();return;}document.documentElement.lang=lang;document.title=L('Production vs sales · SOK HENG','ផលិតកម្មធៀបនឹងការលក់ · SOK HENG');$('report-app').innerHTML=`<header class="fn-header"><div class="od-cluster">${b('menu','☰',`class="mobile-menu" aria-label="${L('Open navigation','បើកម៉ឺនុយ')}"`)}<strong>SOK HENG</strong><span class="sample">${L('Sample data','ទិន្នន័យគំរូ')}</span></div>${b('language',lang==='en'?'ខ្មែរ':'English')}</header><div class="fn-layout"><aside>${nav()}</aside><main class="report-main"><div class="report-heading"><div class="od-field"><span class="eyebrow">${L('REPORTING','របាយការណ៍')}</span><h1>${L('Production vs sales','ផលិតកម្មធៀបនឹងការលក់')}</h1><span class="read-only">${L('Owner & Executive Director · Read only','ម្ចាស់ និងនាយកប្រតិបត្តិ · មើលតែប៉ុណ្ណោះ')}</span></div>${b('info','i',`aria-label="${L('Reporting rules and decisions','ច្បាប់ និងការសម្រេចចិត្តរបាយការណ៍')}"`)}</div><form id="range-form" class="range-bar"><label>${L('From','ចាប់ពី')}<input id="range-start" type="date" required value="${from}"></label><label>${L('To','ដល់')}<input id="range-end" type="date" required value="${to}"></label><label>${L('Product','ផលិតផល')}<select id="product-filter"><option value="all">${L('All products','ផលិតផលទាំងអស់')}</option>${D.products.map(p=>`<option value="${p.id}" ${product===p.id?'selected':''}>${N(p.name)}</option>`).join('')}</select></label><button type="submit" class="primary">${L('Apply','អនុវត្ត')}</button></form>${error?`<p class="ps-error" role="alert">${error}</p>`:''}<p class="subtle" style="margin-bottom:24px">${date(from)} — ${date(to)} · ${L('Recorded quantities','បរិមាណបានកត់ត្រា')}</p><div id="report-content">${body()}</div><footer class="report-footer ps-footer"><span class="subtle">${L('Sample history: 20–30 Sep 2026','ប្រវត្តិគំរូ៖ ២០–៣០ កញ្ញា ២០២៦')}</span><a href="executive-overview.html?${query()}">${L('Executive financial overview →','ទិដ្ឋភាពហិរញ្ញវត្ថុសម្រាប់ថ្នាក់ដឹកនាំ →')}</a></footer></main></div>`;}
function rowQty(r){const p=D.products.find(p=>p.id===r.product);return r.unit===p.code?num(r.qty)+' '+N(p.unit):num(r.qty)+' '+(r.unit==='split-bag'?L('split bags · not yet comparable','បាវចែក · មិនទាន់អាចប្រៀបធៀប'):L('unit missing · not yet comparable','ខ្វះឯកតា · មិនទាន់អាចប្រៀបធៀប'));}
function info(){return `<div class="ps-proposal"><h3>${L('How quantities are counted','របៀបរាប់បរិមាណ')}</h3><p>${L('Unique recorded batch and sale lines only. Debt payments, prefilled receipts, planned loads, picking slips, blank receipt returns and unsold truck returns add no quantity.','រាប់តែបន្ទាត់ផលិតកម្ម និងការលក់ដែលបានកត់ត្រាមិនស្ទួន។ ប្រាក់បំណុល បង្កាន់ដៃរៀបចំ ផែនការផ្ទុក ប័ណ្ណយកទំនិញ បង្កាន់ដៃទទេ និងទំនិញត្រឡប់មិនបន្ថែមបរិមាណទេ។')}</p><h3>${L('Proposals for Z’s review','សំណើសម្រាប់ Z ពិនិត្យ')}</h3><p>${L('Date boundaries: inclusive local calendar days in Asia/Phnom_Penh. Production uses entry time. Sales use the reported sale time; entry time remains visible for late driver records. These choices need agreement.','ព្រំដែនកាលបរិច្ឆេទ៖ រាប់ថ្ងៃចាប់ផ្តើម និងបញ្ចប់តាមម៉ោងភ្នំពេញ។ ផលិតកម្មប្រើម៉ោងបញ្ចូល។ ការលក់ប្រើម៉ោងលក់ដែលបានរាយការណ៍ និងបង្ហាញម៉ោងបញ្ចូលយឺត។ ជម្រើសទាំងនេះត្រូវការការយល់ព្រម។')}</p><p>${L('Corrections and voids: policy is unresolved. This sample uses unambiguous source versions; ambiguous records must be flagged before a complete total can be presented.','ការកែតម្រូវ និងការលុបចោល៖ មិនទាន់កំណត់គោលការណ៍។ គំរូប្រើកំណត់ត្រាច្បាស់លាស់។ កំណត់ត្រាមិនច្បាស់ត្រូវបង្ហាញមុនអាចរាយការណ៍សរុបពេញលេញ។')}</p><p>${L('Split-bag conversion is unresolved. Missing or incompatible units stay separate, with incomplete totals identified. No guessed conversion.','ការបម្លែងបាវចែកមិនទាន់បានកំណត់។ ឯកតាខ្វះ ឬមិនត្រូវគ្នានៅដាច់ដោយឡែក ហើយបង្ហាញសរុបមិនពេញលេញ។ មិនសន្មតការបម្លែង។')}</p><p>${L('Source details are read-only sample snapshots. Live operational detail routes and server authorization are future integration work.','ព័ត៌មានប្រភពជាគំរូសម្រាប់មើលប៉ុណ្ណោះ។ ទំព័រប្រតិបត្តិការពិត និងសិទ្ធិម៉ាស៊ីនមេត្រូវភ្ជាប់ពេលក្រោយ។')}</p></div>`;}
function panel(){const d=detail;let title='',html='';if(d.type==='info'){title=L('Reporting information','ព័ត៌មានរបាយការណ៍');html=info();}else if(d.type==='pending'){title=L('Return records pending','រង់ចាំកំណត់ត្រាត្រឡប់');html=`<dl class="detail-lines">${field(L('Dispatch','ដំណើរ'),'DSP-0928-02')}${field(L('Driver','អ្នកបើកបរ'),L('Sok','សុខ'))}${field(L('Recording','ការកត់ត្រា'),L('Partially entered','បានបញ្ចូលមួយផ្នែក'))}${field(L('Unentered quantity','បរិមាណមិនទាន់បញ្ចូល'),L('Unknown','មិនទាន់ដឹង'))}</dl><p class="detail-note">${L('Missing return records do not mean zero sales. Continue recording in the existing driver-sales workflow. No quantities are inferred here.','កំណត់ត្រាត្រឡប់ខ្វះមិនមានន័យថាគ្មានការលក់។ បន្តកត់ត្រាក្នុងលំហូរការលក់តាមអ្នកបើកបរ។ មិនសន្មតបរិមាណនៅទីនេះទេ។')}</p>`;}else if(d.type==='sources'){const p=D.products.find(x=>x.id===d.product),rows=D.records(from,to,d.product).filter(r=>d.kind==='all'||(d.kind==='sales'&&r.kind!=='production')||r.kind===d.kind);title=N(p.name);html=`<p class="subtle">${date(from)} — ${date(to)} · ${N(p.unit)}</p><div class="ps-source-tabs" aria-label="${L('Source filters','តម្រងប្រភព')}">${['all','production','sales','walkin','driver'].map(k=>b('kind',channel(k),`data-kind="${k}" aria-pressed="${d.kind===k}"`)).join('')}</div>${rows.length?rows.map(r=>`<article class="ps-source"><div class="ps-source-top"><strong>${r.ref}</strong><strong>${rowQty(r)}</strong></div><span>${channel(r.kind)} · ${date(r.date)} ${r.time}</span>${r.customer?`<span class="subtle">${N(r.customer)}${r.dispatch?' · '+r.dispatch:''}</span>`:''}${r.unit!==p.code?`<span class="pill">${L('Not yet comparable','មិនទាន់អាចប្រៀបធៀប')}</span>`:''}${b('record',L('Open source record →','បើកកំណត់ត្រាប្រភព →'),`class="table-link" data-id="${r.id}"`)}</article>`).join(''):`<div class="ps-empty">${L('No recorded activity for this source in the selected period.','គ្មានសកម្មភាពបានកត់ត្រាសម្រាប់ប្រភពនេះក្នុងរយៈពេលបានជ្រើស។')}</div>`}`;}else if(d.type==='record'){const r=D.rows.find(x=>x.id===d.id),p=D.products.find(x=>x.id===r.product);title=r.ref;if(scenario==='restricted'){html=state(L('Source access restricted','សិទ្ធិចូលប្រភពត្រូវបានកម្រិត'),L('Your reporting access does not grant access to this original record. Contact your administrator. Report filters remain unchanged.','សិទ្ធិរបាយការណ៍មិនផ្តល់សិទ្ធិចូលកំណត់ត្រាដើមនេះទេ។ សូមទាក់ទងអ្នកគ្រប់គ្រង។ តម្រងរបាយការណ៍មិនផ្លាស់ប្តូរ។'));}else{html=`<span class="sample">${L('Sample source · Read only','ប្រភពគំរូ · មើលតែប៉ុណ្ណោះ')}</span><dl class="detail-lines">${field(L('Reference','លេខយោង'),r.ref)}${field(L('Source','ប្រភព'),channel(r.kind))}${field(L('Product','ផលិតផល'),N(p.name))}${field(L('Quantity','បរិមាណ'),rowQty(r))}${field(r.kind==='production'?L('Production entry','ការបញ្ចូលផលិតកម្ម'):L('Reported sale time','ពេលលក់បានរាយការណ៍'),date(r.date)+' '+r.time+' (UTC+07:00)')}${r.kind!=='production'?field(L('Entered at','បានបញ្ចូលនៅ'),r.entered+' (UTC+07:00)'):''}${r.customer?field(L('Customer','អតិថិជន'),N(r.customer)):''}${r.dispatch?field(L('Dispatch','ដំណើរ'),r.dispatch):''}${r.kind!=='production'?field(L('Payment coverage','ស្ថានភាពទូទាត់'),r.payment==='partial'?L('Partially paid','បានបង់មួយផ្នែក'):r.payment==='unpaid'?L('Unpaid','មិនទាន់បង់'):L('Paid','បានបង់')):''}</dl><p class="detail-note">${L('This is the supporting sample record. The original operational detail page is not connected. Production entry and sale corrections remain outside Reporting.','នេះជាកំណត់ត្រាគំរូគាំទ្រ។ ទំព័រព័ត៌មានប្រតិបត្តិការដើមមិនទាន់ភ្ជាប់។ ការបញ្ចូលផលិតកម្ម និងកែតម្រូវការលក់នៅក្រៅរបាយការណ៍។')}</p>`;}}
$(embedded?'production-detail':'report-detail').innerHTML=`<header>${history.length?b('back',L('Back','ត្រឡប់')):''}<h2 id="production-detail-title">${title}</h2>${b('close',L('Close','បិទ'))}</header><div class="content">${html}</div>`;}
function open(d){if(!detail)opener=document.activeElement;else history.push({...detail,scroll:$(embedded?'production-detail':'report-detail').scrollTop});detail=d;panel();if(!$(embedded?'production-detail':'report-detail').open)$(embedded?'production-detail':'report-detail').showModal();$(embedded?'production-detail':'report-detail').scrollTop=0;}
function sync(){const q=new URLSearchParams({lang,from,to,product});if(scenario)q.set('scenario',scenario);window.history.replaceState(null,'','?'+q.toString());}
function load(){loading=true;render();setTimeout(()=>{loading=false;render();},scenario==='loading'?1800:400);}
document.addEventListener('submit',e=>{if(e.target.id!=='range-form')return;e.preventDefault();const a=$('range-start').value,z=$('range-end').value;if(!valid(a)||!valid(z)||a>z){error=L('Enter valid dates with the start on or before the end.','សូមបញ្ចូលកាលបរិច្ឆេទត្រឹមត្រូវ ដោយថ្ងៃចាប់ផ្តើមមុន ឬស្មើថ្ងៃបញ្ចប់។');render();return;}from=a;to=z;product=$('product-filter').value;error='';sync();load();});
document.addEventListener('click',e=>{const t=e.target.closest('[data-act]');if(!t)return;const a=t.dataset.act;if(a==='sources')open({type:'sources',product:t.dataset.product,kind:t.dataset.kind});if(a==='record')open({type:'record',id:t.dataset.id});if(a==='info'||a==='pending')open({type:a});if(a==='kind'){detail.kind=t.dataset.kind;panel();}if(a==='back'){const prev=history.pop();detail=prev;panel();$(embedded?'production-detail':'report-detail').scrollTop=prev.scroll||0;}if(a==='close')$(embedded?'production-detail':'report-detail').close();if(a==='language'){const draft={from:$('range-start').value,to:$('range-end').value,product:$('product-filter').value};lang=lang==='en'?'km':'en';sync();render();$('range-start').value=draft.from;$('range-end').value=draft.to;$('product-filter').value=draft.product;if(detail)panel();}if(a==='retry'){failed=false;load();}if(a==='menu'){$('report-nav').innerHTML=`<header><h2>${L('Navigation','ម៉ឺនុយ')}</h2>${b('nav-close',L('Close','បិទ'))}</header><div class="content">${nav()}</div>`;$('report-nav').showModal();}if(a==='nav-close')$('report-nav').close();});
$(embedded?'production-detail':'report-detail').addEventListener('close',()=>{detail=null;history=[];opener?.focus();});
function fragment(){return `<section class="production-embedded"><div class="od-row"><h2>${L('Production vs sales','ផលិតកម្មធៀបនឹងការលក់')}</h2>${b('info','i',`aria-label="${L('Production reporting rules','ច្បាប់របាយការណ៍ផលិតកម្ម')}"`)}</div><label class="ps-product-filter">${L('Product','ផលិតផល')}<select id="production-product"><option value="all">${L('All products','ផលិតផលទាំងអស់')}</option>${D.products.map(p=>`<option value="${p.id}" ${product===p.id?'selected':''}>${N(p.name)}</option>`).join('')}</select></label>${body()}</section>`;}
document.addEventListener('change',e=>{if(e.target.id==='production-product'){product=e.target.value;render();}});
window.ProductionReport={render(options){lang=options.lang;from=options.from;to=options.to;scenario=options.pending?'pending':options.scenario||'';loading=false;failed=false;return `<div id="production-report-content">${fragment()}</div>`;}};
if(!embedded)load();
})();
